/**
 * throw 开关的实例注册表（供 setThrowOnCode 自由函数联动已初始化实例）。
 *
 * 放在 @cloudbase/app 包内（而非 @cloudbase/utilities），避免这些模块级状态
 * 被其它同样依赖 utilities 的包共享，把作用域限制在 js-sdk 实例内存级别。
 */

const throwConfigRegistry = new Set<{ throw?: boolean }>()

/**
 * 注册一个实例的 config 对象，供 setThrowOnCode 自由函数联动改写其 throw。
 * 由 app.init() 在实例 config 构造完成后调用。
 */
export function registerThrowConfig(config: { throw?: boolean }) {
  if (config && typeof config === 'object') {
    throwConfigRegistry.add(config)
  }
}

/**
 * 自由函数形式的 setThrowOnCode：改写所有已注册实例的 config.throw。
 * 兼容 node-sdk 顶层导出用法；实例级更推荐 app.setThrowOnCode(value)。
 */
export function setThrowOnCode(value: boolean) {
  throwConfigRegistry.forEach((config) => {
    config.throw = value
  })
}
